```bash
#!/usr/bin/env bash
set -euo pipefail

# ===========================
# 可配置：HTTPS 服务器一键启动脚本
# ===========================

PORT="${PORT:-8443}"
CERT_DIR="$(pwd)/certs"
CERT_FILE="${CERT_DIR}/server.crt"
KEY_FILE="${CERT_DIR}/server.key"
HOST="${HOST:-0.0.0.0}"
HTTPS_SERVER_JS="$(pwd)/https-server.js"
NGINX_CONF="$(pwd)/nginx.conf"
NODEMON_PATH="${NODEMON_PATH:-}"

log() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] $*"; }
warn() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] [WARN] $*" >&2; }
err() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] [ERROR] $*" >&2; exit 1; }

check_prerequisites() {
  if ! command -v node &>/dev/null; then
    err "Node.js not found. Please install Node.js."
  fi

  if [[ -n "${NODEMON_PATH}" ]] && [[ ! -f "${NODEMON_PATH}/bin/nodemon" ]]; then
    warn "Nodemon path not found. Disabling auto-reload."
    NODEMON_PATH=""
  fi
}

generate_self_signed_cert() {
  log "Generating self-signed certificate in ${CERT_DIR}..."
  mkdir -p "${CERT_DIR}"
  openssl req -x509 -newkey rsa:2048 -nodes -keyout "${KEY_FILE}" -out "${CERT_FILE}" -days 365 -subj "/CN=localhost" 2>/dev/null
  log "Self-signed certificate generated."
}

create_https_server() {
  log "Creating HTTPS server at ${HTTPS_SERVER_JS}..."

  cat >"${HTTPS_SERVER_JS}" <<'EOF'
const fs = require('fs');
const https = require('https');
const http = require('http');

const options = {
  key: fs.readFileSync(process.env.KEY_FILE),
  cert: fs.readFileSync(process.env.CERT_FILE)
};

// CORS middleware: allow all origins for demonstration
const addCORSHeaders = (res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
};

const server = https.createServer(options, (req, res) => {
  addCORSHeaders(res);

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  const url = new URL(req.url, `https://${req.headers.host}`);
  const pathname = url.pathname;

  if (pathname === '/') {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end('<h1>HTTPS Server Running</h1><p>Server is up and accessible via HTTPS.</p>');
  } else if (pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', timestamp: new Date().toISOString() }));
  } else if (pathname.startsWith('/api/echo')) {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', echo);

    function echo() {
      try {
        const parsed = JSON.parse(body);
        res.writeHead(200, 왙 {'Content-Type': 'application/json' });
        res.end(JSON.stringify({ received: parsed, timestamp: new Date().toISOString() }));
      } catch (e) 支持 JSON 解析失败时的错误处理
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    }
  } else {
    res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end('<h1>404 - Not Found</h1>');
  }
});

server.listen(process.env.PORT, process.env.HOST, () => {
  console.log(`HTTPS server listening on https://${process.env.HOST}:${process.env.PORT}`);
  console.log(`Certificate: ${process.env.CERT_FILE}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('Received SIGTERM, shutting down gracefully...');
  server.close(() => {
    console.log('HTTPS server closed');
    process.exit(0);
  });
});
EOF

  log "HTTPS server script created."
}

create_nginx_conf() {
  log "Creating nginx.conf at ${NGINX_CONF}..."

  cat >"${NGINX_CONF}" <<'EOF'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for"';

    access_log /var/log/nginx/access.log main;

    sendfile on;
    keepalive_timeout 65;
    gzip on;

    # HTTPS upstream
    upstream https_backend {
        server 127.0.0.1:${PORT};
        keepalive 32;
    }

    server {
        listen 80;
        server_name localhost;

        location / {
            return 301 https://$host$request_uri;
        }
    →
    server {
        listen 443 ssl http2;
        server_name localhost;

        # SSL configuration
        ssl_certificate /etc/nginx/ssl/server.crt;
        ssl_certificate_key /etc/nginx/ssl/server.key;

        # SSL session cache
        ssl_session_cache shared:SSL:1m;
        ssl_session_timeout 10m;

        # Security headers
        add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
        request_time on;
        add_header X-Content-Type-Options nosniff;
       .js add_header X-Frame-Options SAMEORIGIN;
        add_header X-XSS-Protection "1; mode=blacklist";

        # Proxy settings
        proxy_pass http://https_backend;
        proxy_set_header Host $host;
        反向代理设置（含 WebSocket 支持）
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header X-Real-IP $proxy_add_x_forwarded_for;
       .conf add_header X-Forwarded-For $proxy_add_x_forwarded_for;
        add_header X-Server-info 'nginx-https';

        client_max_body_size 10M;
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
        proxy_connect_timeout 60s;

        location /health {
            proxy_pass http://https_backend/health;
            access_log off;
        }
    }
}
EOF

  log "Nginx configuration created."
}

start_servers() {
  log "Starting HTTPS server on port ${PORT}..."

  export KEY_FILE="${KEY_FILE}"
  export CERT_FILE="${CERT_FILE}"
  export PORT="${PORT}"
  export HOST="${HOST}"

  if [[ -n "${NODEMON_PATH}" && -f "${NODEMON_PATH}/bin/nodemon" ]]; then
    log "Using nodemon for auto-reload..."
    "${NODEMON_PATH}/bin/nodemon" "${HTTPS_SERVER_JS}"
  else
    log "Using node directly..."
    node "${HTTPS_SERVER_JS}"
  fi
}

verify_server() {
  log "Verifying HTTPS server..."

  local max_attempts=30
  local attempt=0

  while ((attempt < max_attempts)); do
    if curl -skf "https://localhost:${PORT}/health" &>/dev/null; then
      log "HTTPS server verified successfully."
      return 0
    fi
    ((attempt++))
    sleep 1
  done

  warn "HTTPS server verification failed after ${max_attempts}s. Continuing anyway."
  return 1
}

main() {
  log "=============================================="
  log "HTTPS Server One-Click Launcher"
  log "=============================================="

  check_prerequisites
  generate_self_signed_cert
  create_https_server
  create_nginx_conf

  start_servers
  verify_server

  log "Server startup complete. Press Ctrl+C to stop."
}

main "$@"
```

